class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        INF = float('inf')
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0
        for v in nums:
            half = (v + 1) // 2
            can_sub = v >= k
            sub = v - k if can_sub else None
            both = INF
            if can_sub:
                both = (v - k + 1) // 2
                if half >= k:
                    both = min(both, half - k)
            nd = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for j in range(op1 + 1):
                for p in range(op2 + 1):
                    cur = dp[j][p]
                    if cur == INF:
                        continue
                    nd[j][p] = min(nd[j][p], cur + v)
                    if j < op1:
                        nd[j + 1][p] = min(nd[j + 1][p], cur + half)
                    if can_sub and p < op2:
                        nd[j][p + 1] = min(nd[j][p + 1], cur + sub)
                    if can_sub and j < op1 and p < op2:
                        nd[j + 1][p + 1] = min(nd[j + 1][p + 1], cur + both)
            dp = nd
        return min(min(row) for row in dp)

