class Solution {
public:
    int minArraySum(vector<int>& nums, int k, int op1, int op2) {
        const long long INF = LLONG_MAX / 2;
        vector<vector<long long>> dp(op1 + 1, vector<long long>(op2 + 1, INF));
        dp[0][0] = 0;
        for (int v : nums) {
            long long half = ((long long)v + 1) / 2;
            bool canSub = v >= k;
            long long sub = canSub ? v - k : 0;
            long long both = INF;
            if (canSub) {
                both = ((long long)(v - k) + 1) / 2;
                if (half >= k) both = min(both, half - k);
            }
            vector<vector<long long>> nd(op1 + 1, vector<long long>(op2 + 1, INF));
            for (int j = 0; j <= op1; j++)
                for (int p = 0; p <= op2; p++) {
                    long long cur = dp[j][p];
                    if (cur >= INF) continue;
                    nd[j][p] = min(nd[j][p], cur + v);
                    if (j < op1) nd[j + 1][p] = min(nd[j + 1][p], cur + half);
                    if (canSub && p < op2) nd[j][p + 1] = min(nd[j][p + 1], cur + sub);
                    if (canSub && j < op1 && p < op2) nd[j + 1][p + 1] = min(nd[j + 1][p + 1], cur + both);
                }
            dp = move(nd);
        }
        long long ans = INF;
        for (auto& row : dp) for (long long x : row) ans = min(ans, x);
        return (int)ans;
    }
};

