            if (half >= k) both = Math.min(both, half - k);
        }
        const nd = Array.from({length: op1 + 1}, () => new Array(op2 + 1).fill(INF));
        for (let j = 0; j <= op1; j++)
            for (let p = 0; p <= op2; p++) {
                const cur = dp[j][p];
                if (cur === INF) continue;
                nd[j][p] = Math.min(nd[j][p], cur + v);
                if (j < op1) nd[j + 1][p] = Math.min(nd[j + 1][p], cur + half);
                if (canSub && p < op2) nd[j][p + 1] = Math.min(nd[j][p + 1], cur + sub);
                if (canSub && j < op1 && p < op2) nd[j + 1][p + 1] = Math.min(nd[j + 1][p + 1], cur + both);
            }
        dp = nd;
    }
    return Math.min(...dp.flat());
};

