class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        from functools import lru_cache
        n = len(nums)
        @lru_cache(maxsize=None)
        def solve(i, j, p):
            if i == n:
                return 0
            v = nums[i]
            best = v + solve(i + 1, j, p)
            if j > 0:
                best = min(best, (v + 1) // 2 + solve(i + 1, j - 1, p))
            if p > 0 and v >= k:
                best = min(best, v - k + solve(i + 1, j, p - 1))
                b = (v - k + 1) // 2
                h = (v + 1) // 2
                if h >= k:
                    b = min(b, h - k)
                if j > 0:
                    best = min(best, b + solve(i + 1, j - 1, p - 1))
            return best
        return solve(0, op1, op2)

