class Solution {
    vector<int> nums_; int k_; int n_;
    vector<vector<vector<long long>>> memo_;
    long long solve(int i, int j, int p) {
        if (i == n_) return 0;
        long long& res = memo_[i][j][p];
        if (res != -1) return res;
        long long v = nums_[i];
        res = v + solve(i + 1, j, p);
        if (j > 0) res = min(res, (v + 1) / 2 + solve(i + 1, j - 1, p));
        if (p > 0 && v >= k_) {
            res = min(res, v - k_ + solve(i + 1, j, p - 1));
            long long b = ((v - k_) + 1) / 2, h = (v + 1) / 2;
            if (h >= k_) b = min(b, h - k_);
            if (j > 0) res = min(res, b + solve(i + 1, j - 1, p - 1));
        }
        return res;
    }
public:
    int minArraySum(vector<int>& nums, int k, int op1, int op2) {
        nums_ = nums; k_ = k; n_ = nums.size();
        memo_.assign(n_ + 1, vector<vector<long long>>(op1 + 1,
              vector<long long>(op2 + 1, -1)));
        return (int)solve(0, op1, op2);
    }
};

