class Solution {
    private int[] nums; private int k, n;
    private Long[][][] memo;
    private long solve(int i, int j, int p) {
        if (i == n) return 0;
        if (memo[i][j][p] != null) return memo[i][j][p];
        long v = nums[i];
        long res = v + solve(i + 1, j, p);
        if (j > 0) res = Math.min(res, (v + 1) / 2 + solve(i + 1, j - 1, p));
        if (p > 0 && v >= k) {
            res = Math.min(res, v - k + solve(i + 1, j, p - 1));
            long b = ((long)(v - k) + 1) / 2, h = ((long) v + 1) / 2;
            if (h >= k) b = Math.min(b, h - k);
            if (j > 0) res = Math.min(res, b + solve(i + 1, j - 1, p - 1));
        }
        return memo[i][j][p] = res;
    }
    public int minArraySum(int[] nums, int k, int op1, int op2) {
        this.nums = nums; this.k = k; this.n = nums.length;
        memo = new Long[n + 1][op1 + 1][op2 + 1];
        return (int) solve(0, op1, op2);
    }
}

